// =====================================================================
// NODO: Armar tabla de movimientos  (modo asistido / formulario)
// ---------------------------------------------------------------------
// Entrada: las filas de la hoja "Movimientos" que leyó el nodo anterior
//          (una fila = un item, con las columnas Fecha, Monto,
//          Descripción y Referencia).
// Salida:  un único item con el campo "html", que es la tabla que el
//          nodo "Subir comprobantes" le muestra al operador.
// =====================================================================

// Escapa los caracteres especiales de HTML (&, <, >) para que un texto
// de la planilla no rompa la tabla ni se interprete como código HTML.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Se descartan las filas vacías (sin monto), por ejemplo filas en blanco
// al final de la planilla.
const movimientos = $input.all().filter(m => m.json.Monto !== undefined && m.json.Monto !== '');

let html;
if (movimientos.length === 0) {
  // Planilla vacía: se avisa al operador en lugar de mostrar una tabla vacía.
  html = '<p><b>No hay movimientos cargados en la planilla.</b> Los comprobantes que subas quedarán como "No encontrada".</p>';
} else {
  // Una fila <tr> por movimiento. La columna Descripción se busca con y
  // sin tilde por si en la planilla el encabezado se escribió sin acento.
  const filas = movimientos.map(m => `<tr>
    <td>${esc(m.json.Fecha)}</td>
    <td>$ ${esc(m.json.Monto)}</td>
    <td>${esc(m.json['Descripción'] ?? m.json.Descripcion)}</td>
    <td>${esc(m.json.Referencia)}</td>
  </tr>`).join('');
  // Tabla completa con encabezado y la cantidad de movimientos.
  html = `<p><b>Movimientos bancarios registrados (${movimientos.length})</b></p>
<table>
  <thead><tr><th>Fecha</th><th>Monto</th><th>Descripción</th><th>Referencia</th></tr></thead>
  <tbody>${filas}</tbody>
</table>`;
}

// Se devuelve un solo item; el formulario lo usa con {{ $json.html }}.
return [{ json: { html } }];

// =====================================================================
// NODO: Separar comprobantes  (modo asistido / formulario)
// ---------------------------------------------------------------------
// Entrada: el item que devuelve el formulario "Subir comprobantes".
//          Si el operador sube varios PDF, n8n los entrega TODOS en un
//          solo item, cada uno como una propiedad binaria distinta
//          (por ejemplo "Comprobantes_de_transferencia_0", "..._1").
// Salida:  un item por PDF, con el archivo siempre bajo la clave "data",
//          igual que los que salen de "Descargar comprobante" (Drive).
//          Así el resto del flujo trata igual a los dos modos.
// =====================================================================

const item = $input.first();          // único item que llega del formulario
const binary = item.binary || {};     // archivos adjuntos (puede venir vacío)
const keys = Object.keys(binary);     // nombres de las propiedades binarias

// El campo es obligatorio en el formulario, pero se controla igual para
// cortar con un error claro si por algún motivo no llegó ningún archivo.
if (keys.length === 0) {
  throw new Error('No se recibió ningún comprobante.');
}

// Se arma un item nuevo por cada archivo:
//  - json.archivo: nombre original del PDF (se usa en el resumen y para
//    guardarlo en "Procesados").
//  - binary.data:  el PDF en sí, que lee "Extraer texto del PDF".
return keys.map((k) => ({
  json: { archivo: binary[k].fileName || k },
  binary: { data: binary[k] },
}));

// =====================================================================
// NODO: Identificar origen  (punto de unión de los dos modos)
// ---------------------------------------------------------------------
// Los dos caminos (formulario y ejecución diaria) llegan a "Extraer
// texto del PDF", que solo devuelve el texto. Este nodo le vuelve a
// agregar a cada texto los datos de su archivo original:
//  - origen:  "formulario" o "diario" (lo usan los nodos If más adelante)
//  - archivo: nombre del PDF
//  - driveId: ID del archivo en Drive (solo modo diario, para moverlo)
//  - binary:  el PDF original (solo modo formulario, para subirlo a
//             "Procesados", porque ese archivo todavía no está en Drive)
// =====================================================================

// Devuelve true si el nodo indicado se ejecutó en esta corrida.
// Se usa try/catch porque consultar un nodo que no corrió puede dar error.
function seEjecuto(nombre) {
  try { return $(nombre).isExecuted; } catch (e) { return false; }
}

const textos = $input.all();                               // textos extraídos, uno por PDF
const desdeFormulario = seEjecuto('Separar comprobantes'); // si corrió, vino del formulario

// Items originales del camino que se ejecutó. Están en el mismo orden
// que los textos, así que el texto i corresponde al archivo i.
const origenes = desdeFormulario
  ? $('Separar comprobantes').all()
  : $('Buscar nuevos comprobantes').all();

return textos.map((t, i) => {
  const src = origenes[i];   // archivo original que corresponde a este texto
  if (desdeFormulario) {
    // Modo formulario: se conserva el PDF (binary) para subirlo a Drive.
    return {
      json: { text: t.json.text || '', origen: 'formulario', archivo: src.json.archivo },
      binary: src.binary,
    };
  }
  // Modo diario: alcanza con el ID de Drive para después mover el archivo.
  return {
    json: { text: t.json.text || '', origen: 'diario', archivo: src.json.name, driveId: src.json.id },
  };
});

// =====================================================================
// NODO: Normalizar y Comparar Datos  (LÓGICA PRINCIPAL)
// ---------------------------------------------------------------------
// Para cada comprobante:
//   1. Extrae del texto del PDF: fecha, monto, destinatario y referencia.
//   2. Busca en la hoja "Movimientos" una fila con la MISMA fecha, monto
//      y referencia.
//   3. Le asigna un Estado: "Conciliada", "No encontrada" o
//      "Requiere revisión".
// Entradas: $('Identificar origen') -> textos de los comprobantes
//           $('Leer movimientos')   -> filas de la planilla del banco
// Salida:   un item por comprobante con los datos extraídos y el Estado.
// Si cambia el formato del comprobante, este es el nodo a modificar.
// =====================================================================

// Tabla para pasar el nombre del mes (como viene en el comprobante) a
// número de dos dígitos. Se incluyen "septiembre" y "setiembre".
const meses = {
  enero: '01', febrero: '02', marzo: '03', abril: '04',
  mayo: '05', junio: '06', julio: '07', agosto: '08',
  septiembre: '09', setiembre: '09', octubre: '10',
  noviembre: '11', diciembre: '12'
};

// Pasa un monto a número. Acepta "10.000", "10.000,50" (formato argentino)
// o un número que ya viene como tal desde Sheets.
// Quita los puntos de miles y cambia la coma decimal por punto.
// Devuelve null si el valor está vacío o no es un número válido.
function aNumero(valor) {
  if (typeof valor === 'number') return valor;
  if (valor === undefined || valor === null || String(valor).trim() === '') return null;
  const n = parseFloat(String(valor).trim().replace(/\./g, '').replace(',', '.'));
  return Number.isNaN(n) ? null : n;
}

const comprobantes = $('Identificar origen').all();  // un item por PDF
const movimientos = $('Leer movimientos').all();     // filas de "Movimientos"

const resultado = comprobantes.map(comp => {
  const texto = comp.json.text;                            // texto completo del PDF
  const lineas = texto.split('\n').map(l => l.trim());     // mismo texto, línea por línea

  // --- FECHA ---------------------------------------------------------
  // Formato del comprobante: 14/septiembre/2026 -> se convierte a
  // 14/09/2026 para compararla con la columna Fecha de la planilla.
  const fechaMatch = texto.match(/(\d{1,2})\/([a-zñáéíóú]+)\/(\d{4})/i);
  let fecha = '';
  if (fechaMatch) {
    const dia = fechaMatch[1].padStart(2, '0');                // "4" -> "04"
    const mes = meses[fechaMatch[2].toLowerCase()] || '00';    // mes desconocido -> "00" (no va a conciliar)
    fecha = `${dia}/${mes}/${fechaMatch[3]}`;
  }

  // --- MONTO ---------------------------------------------------------
  // Toma el primer importe precedido por "$" (ej: "$ 10.000" -> 10000).
  const montoMatch = texto.match(/\$\s?([\d.,]+)/);
  const monto = montoMatch ? aNumero(montoMatch[1]) : null;

  // --- DESTINATARIO --------------------------------------------------
  // Es la línea justo después del primer "CVU" (el CVU de destino).
  // Depende de la posición de las líneas: si el formato cambia, falla.
  const idxCVU = lineas.findIndex(l => l.startsWith('CVU'));
  const destinatario = idxCVU !== -1 ? lineas[idxCVU + 1] : '';

  // --- REFERENCIA ----------------------------------------------------
  // Es la línea después de la que contiene "operación" ("N.° de operación").
  const idxRef = lineas.findIndex(l => l.toLowerCase().includes('operación'));
  const referencia = idxRef !== -1 ? (lineas[idxRef + 1] || '').trim() : '';

  // --- ESTADO --------------------------------------------------------
  // Antes de comparar, nos aseguramos de haber podido extraer los 3 datos clave.
  // Si falta alguno, no tiene sentido decir "No encontrada" (no sabemos si
  // hubiera conciliado o no): se marca aparte para que alguien lo revise a mano.
  let estado;
  if (!fecha || monto === null || !referencia) {
    estado = "Requiere revisión";
  } else {
    // Busca un movimiento con monto, fecha y referencia exactamente iguales.
    // Fecha y Referencia se comparan como texto; Monto como número.
    const match = movimientos.find(m =>
      aNumero(m.json.Monto) === monto &&
      String(m.json.Fecha).trim() == fecha &&
      String(m.json.Referencia).trim() == referencia
    );
    estado = match ? "Conciliada" : "No encontrada";
  }

  // Item de salida. Fecha, Monto, Destinatario, Referencia y Estado van a
  // la hoja "Resultado"; Comprobante, origen y driveId se usan después
  // para el resumen y para archivar el PDF. El binary (PDF) se conserva
  // para el caso del formulario.
  return {
    json: {
      Fecha: fecha,
      Monto: monto === null ? '' : monto,
      Destinatario: destinatario,
      Referencia: referencia,
      Estado: estado,
      Comprobante: comp.json.archivo,
      origen: comp.json.origen,
      driveId: comp.json.driveId
    },
    binary: comp.binary
  };
});
return resultado;

// =====================================================================
// NODO: Armar resumen del mail
// ---------------------------------------------------------------------
// Junta todos los comprobantes procesados en esta corrida en un solo resumen,
// en vez de mandar un mail por cada uno. También arma la pantalla de
// resultado que se le muestra al operador cuando la carga vino del formulario.
// Salida: un único item con
//   - Resumen: HTML del cuerpo del mail (lo usa "Enviar Alerta")
//   - html:    página de resultado (la usa "Mostrar resultado")
//   - origen:  "formulario" o "diario" (lo usa "¿Mostrar resultado?")
// =====================================================================

// Se toman los resultados directamente del nodo de comparación (y no de
// la entrada) porque ahí están todos los campos, incluido el Estado.
const items = $('Normalizar y Comparar Datos').all();
// Todos los items de una corrida tienen el mismo origen; se toma el primero.
const origen = items[0]?.json.origen || 'diario';

// Nombre del operador que completó el formulario (campo opcional).
// Se usa try/catch porque en el modo diario ese nodo no se ejecutó.
let cargadoPor = '';
if (origen === 'formulario') {
  try { cargadoPor = $('Formulario de carga').first().json['Cargado por'] || ''; } catch (e) {}
}

// Escapa caracteres especiales de HTML para no romper el mail ni la página.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Contadores para el resumen: total y cantidad por cada Estado.
const total = items.length;
const conciliadas = items.filter(i => i.json.Estado === "Conciliada").length;
const noEncontradas = items.filter(i => i.json.Estado === "No encontrada").length;
const requiereRevision = items.filter(i => i.json.Estado === "Requiere revisión").length;

// Texto que indica cómo se originó la ejecución (se muestra en mail y pantalla).
const modo = origen === 'formulario'
  ? `Carga manual desde el formulario${cargadoPor ? ` (por ${esc(cargadoPor)})` : ''}`
  : 'Ejecución diaria programada';

// ----- Mail -----
// Una línea por comprobante con destinatario, monto, referencia y estado.
const detalle = items.map(i =>
  `<li>${esc(i.json.Destinatario)} — $${esc(i.json.Monto)} — Ref: ${esc(i.json.Referencia)} — <b>${esc(i.json.Estado)}</b></li>`
).join('');

// Cuerpo completo del mail: origen, totales y detalle.
const resumen = `
<p><b>Origen:</b> ${modo}</p>
<p>Se procesaron <b>${total}</b> comprobante(s):</p>
<ul>
  <li>Conciliadas: ${conciliadas}</li>
  <li>No encontradas: ${noEncontradas}</li>
  <li>Requieren revisión: ${requiereRevision}</li>
</ul>
<p><b>Detalle:</b></p>
<ul>
${detalle}
</ul>
`;

// ----- Pantalla de resultado (solo modo formulario) -----
// Devuelve la etiqueta de color según el Estado:
// verde = Conciliada, amarillo = Requiere revisión, rojo = No encontrada.
const badge = (estado) =>
  estado === 'Conciliada' ? '<span class="badge ok">Conciliada</span>'
  : estado === 'Requiere revisión' ? '<span class="badge warn">Requiere revisión</span>'
  : '<span class="badge bad">No encontrada</span>';

// Una fila de la tabla por comprobante.
const filas = items.map(i => `<tr>
  <td>${esc(i.json.Comprobante)}</td>
  <td>${esc(i.json.Fecha)}</td>
  <td>$${esc(i.json.Monto)}</td>
  <td>${esc(i.json.Destinatario)}</td>
  <td>${esc(i.json.Referencia)}</td>
  <td>${badge(i.json.Estado)}</td>
</tr>`).join('');

// Página completa: título, tarjetas con los totales y tabla de detalle.
// El bloque <style> define el diseño (colores de tarjetas y etiquetas).
const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8">
<title>Resultado de conciliación</title>
<style>
  body { font-family: system-ui, -apple-system, sans-serif; background:#f4f6f8; margin:0; padding:32px; color:#1a1a1a; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  p.sub { color:#555; margin-top:0; }
  .cards { display:flex; gap:16px; margin:24px 0; flex-wrap:wrap; }
  .card { flex:1; min-width:140px; background:#fff; border-radius:10px; padding:16px; box-shadow:0 1px 3px rgba(0,0,0,.1); text-align:center; }
  .card .n { font-size:28px; font-weight:700; }
  .ok-c .n{ color:#1e8e3e } .warn-c .n{ color:#b8860b } .bad-c .n{ color:#d32f2f }
  table { width:100%; border-collapse:collapse; background:#fff; border-radius:10px; overflow:hidden; box-shadow:0 1px 3px rgba(0,0,0,.1); }
  th, td { padding:10px 14px; text-align:left; border-bottom:1px solid #eee; font-size:14px; }
  th { background:#fafafa; font-weight:600; }
  .badge { padding:4px 10px; border-radius:999px; font-size:13px; font-weight:600; white-space:nowrap; }
  .badge.ok { background:#e6f4ea; color:#1e8e3e; }
  .badge.warn { background:#fff8e1; color:#b8860b; }
  .badge.bad { background:#fdecea; color:#d32f2f; }
  .foot { color:#555; font-size:13px; margin-top:16px; }
</style></head>
<body>
  <h1>Conciliación Bancaria Asistida</h1>
  <p class="sub">${modo} &middot; ${total} comprobante(s) procesado(s)</p>
  <div class="cards">
    <div class="card ok-c"><div class="n">${conciliadas}</div>Conciliadas</div>
    <div class="card warn-c"><div class="n">${requiereRevision}</div>Requieren revisión</div>
    <div class="card bad-c"><div class="n">${noEncontradas}</div>No encontradas</div>
  </div>
  <table>
    <thead><tr><th>Comprobante</th><th>Fecha</th><th>Monto</th><th>Destinatario</th><th>Referencia</th><th>Estado</th></tr></thead>
    <tbody>${filas}</tbody>
  </table>
  <p class="foot">El resultado quedó registrado en la planilla, los comprobantes se guardaron en la carpeta "Procesados" de Google Drive y se envió el resumen por correo.</p>
</body></html>`;

// Se devuelve un solo item: así el mail se envía una sola vez por ejecución.
return [{ json: { Resumen: resumen, html, origen } }];
